/* GPO Remediator Enterprise UI — CIS v4.0.0. Real GPO execution stays in the existing backend. */
(() => {
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const client=window.GpoClient;
const state={session:null,service:null,gpoSession:null,inventory:null,readiness:null,readinessError:'',settings:[],history:[],audit:null,auditQuery:'',auditIntegrity:'unknown',catalog:null,plan:null,busy:false,notice:'',query:'',level:'ALL',automation:'ALL',savedView:'ALL',expandedTop:new Set(['1']),expandedSub:new Set(),selectedRule:null,tab:'overview',opsFilter:'ALL',opsQuery:'',theme:client.storage.get('gr-theme','light'),lang:client.storage.get('gr-lang','az'),approval:{reference:'',approver:'',reviewed:false},favorites:new Set(client.storage.favorites()),commandOpen:false,commandQuery:'',notificationOpen:false,confirmAction:null,gpoSearch:'',gpoPickerOpen:false,buildLabel:'2.1.0',selection:{gpoId:'',scopeDn:'',setting:'',value:14,customValue:'',accountScope:'LocalComputers',refresh:'None',firstLink:false}};
let page,bar;
window.GpoI18n.setLanguage(state.lang);
const tr=k=>window.GpoI18n.t(k);
const statusText=v=>({PUBLISHED:say('GPO-da yayımlandı','Published'),NO_CHANGE:say('Dəyişiklik lazım deyil','No change'),DRIFT_DETECTED:say('Dəyişiklik aşkarlanıb','Drift detected'),REFRESH_SCHEDULED:say('gpupdate planlaşdırıldı','gpupdate scheduled'),REFRESH_PARTIAL:say('gpupdate qismən planlaşdırıldı','gpupdate partially scheduled'),REFRESH_NOT_CONFIGURED:say('gpupdate target seçilməyib','gpupdate not configured'),VERIFY_MISMATCH:say('Yoxlama uyğunsuzluğu','Verification mismatch'),REVIEW_REQUIRED:say('Administrator yoxlaması tələb olunur','Review required'),ROLLED_BACK:say('Geri qaytarıldı','Rolled back'),ROLLBACK_REVIEW_REQUIRED:say('Rollback yoxlaması tələb olunur','Rollback review required'),ROLLBACK_DRIFT_DETECTED:say('Rollback-dan sonra drift aşkarlanıb','Drift detected after rollback'),FAILED_SAFE:say('Təhlükəsiz dayandırıldı','Safely stopped'),ENDPOINT_MISMATCH:say('Endpoint siyasəti uyğun deyil','Endpoint mismatch'),REPLICATION_PENDING:say('Replikasiya gözlənilir','Replication pending'),VERIFIED_ON_SAMPLE:say('Endpoint nümunəsində təsdiqləndi','Verified on endpoint sample'),DOMAIN_VALUE_MATCHES_ON_SELECTED_DC:say('Seçilmiş DC-də effektivdir','Effective on selected DC'),ENDPOINT_VERIFICATION_PENDING:say('Endpoint yoxlaması gözlənilir','Endpoint verification pending')}[String(v||'').toUpperCase()]||String(v||'Unknown'));
const stateClass=v=>/DRIFT|MISMATCH|REVIEW|FAIL/.test(String(v||'').toUpperCase())?'bad':/PUBLISHED|NO_CHANGE|VERIFIED|MATCHES|ROLLED_BACK/.test(String(v||'').toUpperCase())?'ok':'pending';
const errorGuidance=e=>{const c=String(e?.code||'');if(/LOGIN|CREDENTIAL|AUTH|OPERATOR/.test(c))return say('Hesabı və delegated icazələri yoxlayın, sonra yenidən qoşulun.','Check the account and delegated permissions, then reconnect.');if(/REPLICATION|SYSVOL/.test(c))return say('AD/SYSVOL replikasiyasını yoxlayın və dəyişiklikdən əvvəl yenidən Verify edin.','Check AD/SYSVOL replication and Verify again before changing anything.');if(/GPO_CHANGED|PLAN_STALE|DRIFT/.test(c))return say('Canlı vəziyyət dəyişib. Köhnə planı istifadə etməyin; yeni plan yaradın.','Live state changed. Do not reuse the old plan; create a fresh plan.');if(/ACCESS|PERMISSION|DENIED/.test(c))return say('Seçilmiş GPO və link hədəfi üçün edit/gPLink icazələrini yoxlayın.','Check edit/gPLink permissions for the selected GPO and target.');if(/REFRESH|ENDPOINT/.test(c))return say('Target host connectivity və effective policy-ni ayrıca yoxlayın.','Check target host connectivity and effective policy separately.');return say('Təkrar etməzdən əvvəl canlı vəziyyəti və Operations evidence-ni yoxlayın.','Review live state and Operations evidence before retrying.');};
async function api(path,body){try{return await client.request('/api'+path,{body,csrfToken:state.session?.csrfToken});}catch(e){if(e.code==='GPO_LOGIN_REQUIRED'){state.inventory=null;state.gpoSession=null;state.readiness=null;state.readinessError='';state.plan=null;}throw e;}}
async function loadCatalog(){if(state.catalog)return;const catalog=await client.request('/benchmark-v4.json?v=1.1.0');if(!Array.isArray(catalog.rules)||!Array.isArray(catalog.sections))throw Error('Invalid benchmark catalog. Rebuild the frontend package.');state.catalog=catalog;}
function syncBackendMappings(){if(!state.catalog)return;const byId=new Map(state.settings.map(x=>[x.id,x]));for(const r of state.catalog.rules){const m=byId.get(r.id);const writable=!!m&&m.automation==='Automated'&&m.handler!=='Manual';r.backendSetting=writable?m.id:null;r.implementation=writable?'live':m?'manual':'unavailable';r.backendMapping=m||null;}state.catalog.meta.liveMappings=state.catalog.rules.filter(r=>r.implementation==='live').length;}
const topSections=()=>state.catalog?.sections.filter(s=>!s.parentId)||[];
const children=id=>state.catalog?.sections.filter(s=>s.parentId===id)||[];
const directRules=id=>state.catalog?.rules.filter(r=>r.sectionId===id)||[];
const descendants=id=>state.catalog?.rules.filter(r=>r.id.startsWith(id+'.'))||[];
function matchesRule(r){const q=state.query.trim().toLowerCase();const view=state.savedView==='ALL'||(state.savedView==='FAVORITES'&&state.favorites.has(r.id))||(state.savedView==='READY'&&r.implementation==='live')||(state.savedView==='HIGH'&&riskFor(r).name==='High');return view&&(!q||(`${r.id} ${r.title} ${r.description}`).toLowerCase().includes(q))&&(state.level==='ALL'||r.level===state.level)&&(state.automation==='ALL'||r.automation===state.automation);}
function riskFor(r){const source=state.settings.find(x=>x.id===(r.backendSetting||r.id)),risk=GpoUiDomain.impact(source?{...source,impactReason:state.lang==='az'?(source.impactReasonAz||source.impactReason):source.impactReason}:null);return {...risk,name:risk.name==='High'?say('Yüksək','High'):risk.name==='Medium'?say('Orta','Medium'):say('Aşağı','Low')};}
function implLabel(r){if(r.implementation==='manual'||r.automation!=='Automated')return `<span class="status-chip manual">${tr('manual')}</span>`;return r.implementation==='live'?`<span class="status-chip ready">${tr('ready')}</span>`:`<span class="status-chip planned">${tr('planned')}</span>`;}
function badges(r){return `<span class="mini-chip level">${esc(r.level)}</span><span class="mini-chip">${r.automation==='Automated'?'AUTO':'MANUAL'}</span>${implLabel(r)}`;}
function domainIcon(id){const map={'1':'⌾','2':'◇','5':'▦','9':'◫','17':'≋','18':'⚙','19':'◉'};return map[id]||'◆';}
function topDomainForRule(r){return topSections().find(s=>r.id===s.id||r.id.startsWith(s.id+'.'));}
function sectionTitle(id){return state.catalog.sections.find(s=>s.id===id)?.title||'';}
function renderSubsection(id,depth=0){const s=state.catalog.sections.find(x=>x.id===id);if(!s)return'';const kids=children(id),rules=directRules(id).filter(matchesRule),matching=descendants(id).filter(matchesRule);if(!matching.length&&!rules.length)return'';const open=state.expandedSub.has(id)||!!state.query;return `<div class="ent-sub depth-${Math.min(depth,3)}"><button class="ent-sub-head" data-subsection="${esc(id)}"><span class="sub-id">${esc(id)}</span><span class="sub-copy"><strong>${esc(s.title)}</strong><small>${matching.length||rules.length} matching · ${s.count} total</small></span><span class="chev">${open?'−':'+'}</span></button>${open?`<div class="ent-sub-body">${kids.map(k=>renderSubsection(k.id,depth+1)).join('')}${rules.map(renderRuleRow).join('')}</div>`:''}</div>`;}
function renderRuleRow(r){const risk=riskFor(r),fav=state.favorites.has(r.id);return `<div class="ent-rule-shell"><button class="ent-rule ${fav?'favorite':''}" data-rule="${esc(r.id)}" aria-label="Open CIS control ${esc(r.id)}: ${esc(r.title)}"><span class="rule-id">${esc(r.id)}</span><span class="rule-copy"><strong>${esc(r.title)}</strong><span class="rule-meta">${badges(r)}<span class="risk-dot ${risk.cls}">${risk.name}</span></span></span><span class="open-arrow">›</span></button><button class="fav-mini ${fav?'active':''}" data-favorite="${esc(r.id)}" title="Favorite" aria-label="${fav?'Remove from favorites':'Add to favorites'}">${fav?'★':'☆'}</button></div>`;}
function renderDomain(s){const rules=descendants(s.id).filter(matchesRule);if(!rules.length)return'';const open=state.expandedTop.has(s.id)||!!state.query,live=rules.filter(r=>r.implementation==='live').length;const l1=rules.filter(r=>r.level==='L1').length,l2=rules.filter(r=>r.level==='L2').length;return `<section class="ent-domain ${open?'open':''}"><button class="ent-domain-head" data-domain="${esc(s.id)}" aria-expanded="${open?'true':'false'}"><span class="domain-icon">${domainIcon(s.id)}</span><span class="domain-title"><span class="domain-kicker">DOMAIN ${esc(s.id)}</span><strong>${esc(s.title)}</strong><small>${rules.length} controls · ${live} ready</small></span><span class="domain-counter"><i>L1</i><b>${l1}</b></span><span class="domain-counter"><i>L2</i><b>${l2}</b></span><span class="domain-progress"><i style="width:${Math.min(100,Math.round((live/Math.max(1,rules.length))*100))}%"></i></span><span class="domain-chevron">${open?'−':'+'}</span></button>${open?`<div class="ent-domain-body">${children(s.id).map(k=>renderSubsection(k.id)).join('')}${directRules(s.id).filter(matchesRule).map(renderRuleRow).join('')}</div>`:''}</section>`;}
const say=(az,en)=>window.GpoI18n.pair(az,en);
const successful=h=>GpoUiDomain.classify(h).compliant;
const needsReview=h=>/FAIL|MISMATCH|REVIEW|PARTIAL|DRIFT/.test(String(h.result?.state||''));
function renderConnection(compact=false){
  const i=state.inventory;
  if(i){const exp=state.gpoSession?.expiresAt?new Date(state.gpoSession.expiresAt):null;const mins=exp?Math.max(0,Math.ceil((exp-Date.now())/60000)):null;return `<div class="conn ${state.readiness?.ready?'ok':'warn'}"><span class="conn-orb"></span><div><small>${state.readiness?.ready?say('Bağlantı hazırdır','Connection ready'):say('Domenə qoşulub · yoxlama tələb olunur','Domain connected · check required')}</small><strong>${esc(i.domain)}</strong><span>${esc(i.domainController)} · ${esc(i.executionUser)}${mins!=null?` · ${say('sessiya','session')} ${mins} min`:''}</span></div><div class="conn-actions"><button data-readiness title="Runs read-only AD/GPO readiness checks">${say('Bağlantını yoxla','Check connection')}</button><button data-disconnect title="Clears delegated credentials from memory">${tr('logout')}</button></div></div>`;}
  if(state.session?.mode!=='WINDOWS')return `<div class="conn warn"><span class="conn-orb"></span><div><strong>${say('İlk quraşdırma','Initial setup')}</strong><span>${say('Domen və domen kontrollerini seçin. Digər məlumatlar avtomatik doldurulur.','Choose the domain and domain controller. Other settings are filled automatically.')}</span></div><button data-settings>${say('Quraşdırmanı aç','Open setup')}</button></div>`;
  return `<form id="gpo-login" class="conn login"><div><strong>${tr('connect')}</strong><p>${say('İcra üçün ayrıca səlahiyyət verilmiş domen hesabını daxil edin. Brauzerdə autentifikasiya olunmuş operator və GPO icra hesabı ayrıdır.','Enter an explicit delegated domain account for execution. The authenticated browser operator and GPO execution identity are separate.')}</p><div class="login-fields"><label>${say('İcra istifadəçisi','Execution username')}<input name="userName" placeholder="DOMAIN\\user" autocomplete="username" required></label><label>${say('Şifrə','Password')}<input name="password" type="password" autocomplete="current-password" required></label></div></div><button class="primary">${say('Qoşul','Connect')}</button></form>`;
}
function environmentHealth(){
  if(!state.inventory)return '';
  const checks=state.readiness?.checks||[];
  return `<section class="health-panel panel"><div class="panel-head"><h2>${say('Bağlantı yoxlaması','Connection checks')}</h2><button data-readiness>${say('Yenidən yoxla','Check again')}</button></div>${state.readinessError?`<div class="gr-auto-note warn">${esc(state.readinessError)}</div>`:''}${!checks.length?`<p>${say('Domenə giriş alınıb. Hazırlıq yoxlaması hələ tamamlanmayıb.','Domain sign-in succeeded. Readiness checks have not completed yet.')}</p>`:`<div class="health-grid">${checks.map(c=>`<div class="health-item ${c.state==='PASS'?'ok':c.state==='FAIL'?'bad':'pending'}"><span>${c.state==='PASS'?'✓':c.state==='FAIL'?'!':'·'}</span><div><strong>${esc(c.label)}</strong><small>${esc(c.message)}</small></div></div>`).join('')}</div>`}</section>`;
}
function dashboardView(){
  const total=state.catalog.rules.length,ready=state.catalog.rules.filter(r=>r.implementation==='live').length;
  const quality=state.history.map(GpoUiDomain.classify),published=quality.filter(x=>x.publication==='published').length,replicated=quality.filter(x=>x.replication==='converged').length,effective=quality.filter(x=>x.effective==='verified').length,attention=quality.filter(x=>x.attention).length;
  return `<div class="hero"><div><span class="eyebrow">${say('ƏMƏLİYYAT İCMALI','OPERATIONS OVERVIEW')}</span><h1>${tr('dashboard')}</h1><p>${say('Operator, publication, replication və faktiki siyasət vəziyyətini ayrı izləyin.','Track operator, publication, replication, and effective-policy state independently.')}</p></div><div class="hero-badge"><span>${say('ROL','ROLE')}</span><strong>${esc(state.session?.role||'—')}</strong></div></div>${renderConnection()}<div class="dash-grid assurance-metrics"><div class="kpi primary"><span>${say('Yayımlanıb','Published')}</span><strong>${published}</strong><small>${say('GPO dəyəri yazılıb','GPO value recorded')}</small></div><div class="kpi"><span>${say('Replikasiya tamamdır','Replicated')}</span><strong>${replicated}</strong><small>AD / SYSVOL</small></div><div class="kpi"><span>${say('Faktiki təsdiqlənib','Effective verified')}</span><strong>${effective}</strong><small>${say('Sample və ya DC yoxlaması','Sample or DC evidence')}</small></div><div class="kpi danger"><span>${say('Diqqət tələb edir','Review required')}</span><strong>${attention}</strong><small>${say('Drift, mismatch və ya natamamlıq','Drift, mismatch, or incomplete')}</small></div></div><section class="simple-steps"><a href="#/dashboard"><b>1</b>${say('Delegated hesabla qoşul','Connect delegated identity')}</a><a href="#/benchmark"><b>2</b>${say(`${ready}/${total} qaydadan seç`,`Choose from ${ready}/${total} controls`)}</a><a href="#/operations"><b>3</b>${say('Mərhələləri ayrıca yoxla','Review each assurance stage')}</a></section>${environmentHealth()}<section class="panel quick-start"><div><h2>${say('Növbəti addım','Next step')}</h2><p>${say('Read-only plan yaradın; Apply yalnız rol, scope, write authorization və təsdiqdən sonra açılır.','Generate a read-only plan; Apply requires role, scope, write authorization, and confirmation.')}</p></div><a class="primary-action" href="#/benchmark">${say('Benchmark-i aç','Browse benchmark')} →</a></section>`;
}
function benchmarkView(){const m=state.catalog.meta;return `<div class="hero compact"><div><span class="eyebrow">CIS BENCHMARK LIBRARY</span><h1>${tr('domains')}</h1><p>Navigate by domain, use saved views, and favorite recurring controls without flattening the benchmark hierarchy.</p></div><div class="hero-actions"><div class="hero-badge"><span>CIS</span><strong>v4.0.0</strong></div></div></div><div class="catalog-summary"><span><b>${topSections().length}</b> domains</span><span><b>${m.reportedRecipeCount}</b> controls</span><span><b>${m.levels.L1}</b> L1</span><span><b>${m.levels.L2}</b> L2</span><span><b>${m.liveMappings}</b> ready</span><span><b>${state.favorites.size}</b> favorites</span></div><div class="saved-views"><button data-view="ALL" class="${state.savedView==='ALL'?'active':''}">All controls</button><button data-view="FAVORITES" class="${state.savedView==='FAVORITES'?'active':''}">★ Favorites</button><button data-view="READY" class="${state.savedView==='READY'?'active':''}">Remediation ready</button><button data-view="HIGH" class="${state.savedView==='HIGH'?'active':''}">High impact</button></div><section class="catalog-shell"><div class="catalog-toolbar"><div class="searchbox"><span>⌕</span><input id="catalog-search" value="${esc(state.query)}" placeholder="${tr('search')}"></div><select id="catalog-level"><option value="ALL">${tr('allLevels')}</option><option value="L1" ${state.level==='L1'?'selected':''}>L1</option><option value="L2" ${state.level==='L2'?'selected':''}>L2</option><option value="NG" ${state.level==='NG'?'selected':''}>NG</option></select><select id="catalog-automation"><option value="ALL">${tr('allTypes')}</option><option value="Automated" ${state.automation==='Automated'?'selected':''}>Automated</option><option value="Manual" ${state.automation==='Manual'?'selected':''}>Manual</option></select></div><div class="domain-stack">${topSections().map(renderDomain).join('')}</div></section>`;}
function ensureSelection(){const r=state.selectedRule;if(!r)return;state.selection.setting=r.backendSetting||'';const st=state.settings.find(x=>x.id===r.backendSetting);if(st){if(st.allowValueOverride&&state.selection.value==null)state.selection.value=st.suggested;if(st.requiresInput&&state.selection.customValue==null)state.selection.customValue=st.inputDefault||'';state.selection.accountScope=st.domainPolicySensitive?'Domain':'LocalComputers';}if(state.inventory){if(!state.inventory.gpos.some(g=>g.id===state.selection.gpoId&&g.selectable))state.selection.gpoId='';const scopes=st?.domainPolicySensitive?state.inventory.scopes.filter(x=>x.kind==='Domain'):state.inventory.scopes;if(!scopes.some(x=>x.dn===state.selection.scopeDn))state.selection.scopeDn=scopes[0]?.dn||'';}}
function selectedGpo(){return state.inventory?.gpos.find(g=>g.id===state.selection.gpoId)||null;}
function relevantHistory(rule){return state.history.filter(h=>h.plan?.selection?.setting===(rule.backendSetting||rule.id)).sort((a,b)=>Date.parse(b.updatedAt||0)-Date.parse(a.updatedAt||0));}
function gpoPicker(){const i=state.inventory;if(!i)return'';const selected=selectedGpo();const q=state.gpoSearch.trim().toLowerCase();const items=i.gpos.filter(g=>!q||g.name.toLowerCase().includes(q)).slice(0,40);return `<div class="gpo-picker"><button type="button" class="gpo-picker-trigger" data-gpo-toggle><span><small>Selected GPO</small><strong>${selected?esc(selected.name):'Choose a Group Policy Object'}</strong></span><b>⌄</b></button>${state.gpoPickerOpen?`<div class="gpo-popover"><div class="gpo-search"><span>⌕</span><input id="gpo-search" value="${esc(state.gpoSearch)}" placeholder="Search GPO by name…" autofocus></div><div class="gpo-results">${items.map(g=>`<button type="button" data-gpo="${esc(g.id)}" ${g.selectable?'':'disabled'}><span><strong>${esc(g.name)}</strong><small>${g.protected?'Protected · ':''}${g.selectable?'Selectable':'Unavailable for this workflow'}</small></span><b>${g.id===state.selection.gpoId?'✓':'›'}</b></button>`).join('')||'<div class="no-results">No matching GPO</div>'}</div></div>`:''}</div>`;}
function stepper(active){const steps=['Control','Target','Preview','Approval','Apply','Verify'];return `<div class="stepper">${steps.map((s,idx)=>`<div class="step ${idx+1<active?'done':idx+1===active?'active':''}"><b>${idx+1<active?'✓':idx+1}</b><span>${s}</span></div>`).join('')}</div>`;}
function currentStep(){const run=state.selectedRule?relevantHistory(state.selectedRule)[0]:null;const step=GpoUiDomain.workflowStep({plan:state.plan,approvalReviewed:state.approval.reviewed,run});return !run&&!state.plan&&state.selection.gpoId?2:step;}
function controlHeader(r){const d=topDomainForRule(r),risk=riskFor(r);return `<div class="control-header"><button class="back-link" data-back>← ${tr('back')}</button><div class="control-title-row"><div class="control-id-block"><span>${esc(r.id)}</span><small>${esc(d?.title||'CIS Control')}</small></div><div class="control-title"><div class="control-badges">${badges(r)}<span class="risk-pill ${risk.cls}">${risk.name} ${tr('risk')}</span></div><h1>${esc(r.title)}</h1></div><button class="favorite-action ${state.favorites.has(r.id)?'active':''}" data-favorite="${esc(r.id)}">${state.favorites.has(r.id)?'★ Saved':'☆ Save'}</button></div>${stepper(currentStep())}<div class="control-tabs">${[['overview',tr('overview')],['remediation',tr('remediation')],['impact',tr('impact')],['verification',tr('verification')],['audit',tr('audit')]].map(([k,l])=>`<button data-tab="${k}" class="${state.tab===k?'active':''}">${l}</button>`).join('')}</div></div>`;}
function overviewTab(r){const risk=riskFor(r);return `<div class="tab-grid"><section class="content-card span2"><span class="card-kicker">CONTROL INTENT</span><h2>What this control changes</h2><p class="long-copy">${esc(r.description||'No description was included in the imported benchmark text.')}</p></section><section class="content-card"><span class="card-kicker">RECOMMENDED STATE</span><h2>${esc(r.recommended||'See benchmark text')}</h2><p>This value comes from the imported CIS Benchmark v4.0.0 recipe.</p></section><section class="content-card risk-card ${risk.cls}"><span class="card-kicker">OPERATIONAL RISK</span><h2>${risk.name}</h2><p>${esc(risk.copy)}</p></section><section class="content-card"><span class="card-kicker">IMPLEMENTATION</span><h2>${r.implementation==='live'?'Automated remediation ready':r.implementation==='manual'?'Manual / read-only control':'Mapping unavailable'}</h2><p>${r.implementation==='live'?'This control has a server-authoritative production mapping and can generate a real GPO preview.':r.implementation==='manual'?'The imported CIS catalog does not classify this control as safely automated. The product keeps it visible but blocks automatic writes.':'No server-authoritative mapping is available for this control.'}</p></section><section class="content-card"><span class="card-kicker">CLASSIFICATION</span><div class="fact-list"><span><b>Level</b>${esc(r.level)}</span><span><b>Type</b>${esc(r.automation)}</span><span><b>Section</b>${esc(sectionTitle(r.sectionId))}</span><span><b>Benchmark</b>CIS v4.0.0</span></div></section><section class="content-card span2 help-card"><span class="card-kicker">CONTEXTUAL GUIDANCE</span><div class="guidance-grid"><div><b>When to use</b><p>Apply when this control belongs to the intended server/workstation baseline and the selected GPO scope is correct.</p></div><div><b>Before change</b><p>Review application dependencies, policy precedence and affected objects. Generate a read-only plan first.</p></div><div><b>After change</b><p>Verify GPO publication, link state, gpupdate and effective policy. Pending probes must remain pending.</p></div></div></section></div>`;}
function targetForm(r){const i=state.inventory,s=state.selection,st=state.settings.find(x=>x.id===r.backendSetting);if(!i)return `<div class="locked-state">${renderConnection()}<h3>${say('Real GPO və tətbiq sahəsini seçmək üçün domenə qoşulun.','Connect to the domain to select a real GPO and apply scope.')}</h3></div>`;const scopes=st?.domainPolicySensitive?i.scopes.filter(x=>x.kind==='Domain'):i.scopes,targetIsUser=String(st?.scope||'Computer').toLowerCase()==='user';const targetLabel=targetIsUser?say('İstifadəçilər','Users'):say('Kompüterlər','Computers');const desired=st?.requiresInput?`<label>${esc(st.inputLabel||say('Tələb olunan dəyər','Required value'))}<input name="customValue" value="${esc(s.customValue||st.inputDefault||'')}" maxlength="4096" required></label>`:st?.allowValueOverride?`<label>${say('Tətbiq ediləcək dəyər','Desired value')} <span class="unit">${esc(st.unit||'value')}</span><input type="number" name="value" min="${st.minimum??0}" max="${st.maximum??99999}" value="${s.value}"></label>`:`<label>${say('Tətbiq ediləcək dəyər','Desired benchmark state')}<input disabled value="${esc(st?.recommended||'Fixed production mapping')}"></label>`;return `<form id="gpo-selection" class="target-form"><div class="form-section-title"><span>01</span><div><small>${say('HƏDƏF','TARGET')}</small><h2>${say('Kimə tətbiq olunacaq?','Who will this apply to?')}</h2></div></div>${gpoPicker()}<div class="target-scope-note"><span>${targetIsUser?'U':'PC'}</span><div><strong>${targetLabel}</strong><small>${say(`Seçilən domen/OU daxilindəki ${targetLabel.toLocaleLowerCase('az-AZ')} hədəflənəcək.`,`Targets ${targetLabel.toLowerCase()} inside the selected domain/OU.`)}</small></div></div><div class="form-grid"><label>${say('Siyasət növü','Policy type')}<input disabled value="${targetLabel}"></label><label>${say('Tətbiq sahəsi (OU / domen)','Apply scope (OU / domain)')}<select name="scopeDn" required>${scopes.map(x=>`<option value="${esc(x.dn)}" ${s.scopeDn===x.dn?'selected':''}>${esc(x.name)} · ${esc(x.kind)} · ${esc(x.dn)}</option>`).join('')}</select><small>${say('GPO fərdi ada deyil, seçilən AD sahəsinə link olunur.','A GPO links to the selected AD scope, not directly to a typed name.')}</small></label>${r.implementation==='live'?desired:`<label>${say('Tətbiq ediləcək dəyər','Desired value')}<input disabled value="Manual/review-only control"></label>`}<label>${say('Yeniləmə','Post-Apply refresh')}<select name="refresh"><option value="None" ${s.refresh==='None'?'selected':''}>${say('İndi yeniləmə','Do not run now')}</option><option value="Pdc" ${s.refresh==='Pdc'?'selected':''}>PDC emulator</option><option value="Scope" ${s.refresh==='Scope'?'selected':''}>${say('Seçilmiş sahədəki kompüterlər','Computers in selected scope')}</option></select><small>${say('gpupdate yalnız Apply-dan sonra ayrıca başladılır.','gpupdate is triggered separately after Apply.')}</small></label></div><label class="switch-row"><input type="checkbox" name="firstLink" ${s.firstLink?'checked':''}><span><b>${say('Ən yüksək link prioriteti','Highest link priority')}</b><small>${say('Mövcud filtering və Enforced sazlamaları dəyişmir.','Existing filtering and Enforced settings are preserved.')}</small></span></label><button class="primary-action" ${r.implementation==='live'&&s.gpoId?'':'disabled'}>${tr('preview')} <span>→</span></button></form>`;}
function impactTab(r){const risk=riskFor(r),g=selectedGpo(),scope=state.inventory?.scopes.find(x=>x.dn===state.selection.scopeDn),live=state.plan?.preview?.impact,conflicts=live?.conflicts||[],ao=live?.affectedObjects;const graphNodes=[['Domain root',state.inventory?.domain||'Not connected'],['Selected GPO',g?.name||'Not selected'],['Target scope',scope?.name||'Not selected'],['Effective policy',state.plan?'Verification after Apply':'Preview required']];return `<div class="impact-layout"><section class="impact-hero ${risk.cls}"><span>${say('TƏXMİNİ ƏMƏLİYYAT TƏSİRİ','ESTIMATED OPERATIONAL IMPACT')}</span><h2>${risk.name}</h2><p>${esc(risk.copy)} ${say('Bu server mapping metadata-sına əsaslanan əməliyyat istiqamətidir; yekun risk qərarı deyil.','This is operational guidance from server mapping metadata, not a final risk decision.')}</p></section><div class="impact-grid"><section class="content-card"><span class="card-kicker">SELECTED GPO</span><h2>${g?esc(g.name):'Not selected'}</h2><div class="fact-list"><span><b>Protected</b>${g?.protected?'Yes':'No'}</span><span><b>Selectable</b>${g?.selectable?'Yes':'No'}</span></div></section><section class="content-card"><span class="card-kicker">TARGET SCOPE</span><h2>${scope?esc(scope.name):'Not selected'}</h2><p>${scope?esc(scope.dn):'Choose a domain/OU target in Remediation.'}</p></section><section class="content-card span2 conflict-card"><div class="card-title-row"><div><span class="card-kicker">POLICY CONFLICT GRAPH</span><h2>Inheritance & precedence path</h2></div><span class="probe-badge">${live?'LIVE ANALYSIS':'PREVIEW REQUIRED'}</span></div><div class="policy-graph">${graphNodes.map((n,i)=>`<div class="graph-node ${i===1?'focus':''}"><span>${i+1}</span><div><small>${esc(n[0])}</small><strong>${esc(n[1])}</strong></div></div>${i<graphNodes.length-1?'<i>↓</i>':''}`).join('')}</div>${live?`<div class="warning-list">${conflicts.length?conflicts.map((c,i)=>`<div><b>${esc(c.severity||'!')}</b><span>${esc(c.message)}</span></div>`).join(''):'<div><b>✓</b><span>No conflict was detected by the current bounded analysis; this is not a full RSoP guarantee.</span></div>'}</div><p class="engine-note">Inheritance: ${esc(live.inheritance)} · WMI filter: ${esc(live.wmiFilter||'none')} · Security filtering: ${esc((live.securityFiltering||[]).join(', ')||'none detected')}</p>`:'<p class="engine-note">Generate a read-only plan to run live inheritance, precedence, security filtering and WMI analysis.</p>'}</section><section class="content-card span2 affected-card"><div class="card-title-row"><div><span class="card-kicker">PRE-FILTER SCOPE INVENTORY</span><h2>Objects in selected scope before policy filtering</h2></div><span class="probe-badge">${ao?'LIVE INVENTORY':'PREVIEW REQUIRED'}</span></div><div class="object-stats"><div><strong>${ao?.computers??'—'}</strong><span>Computers</span></div><div><strong>${ao?.servers??'—'}</strong><span>Servers</span></div><div><strong>${ao?.workstations??'—'}</strong><span>Workstations</span></div><div><strong>${ao?.disabled??'—'}</strong><span>Disabled</span></div></div>${ao?`<div class="object-placeholder"><span>⌁</span><p>Counts do not apply security/WMI filtering or resultant-policy evaluation. ${ao.truncated?'Inventory capped at 5,000 objects. ':''}${ao.users?`${ao.users} enabled users in scope. `:''}Sample: ${esc((ao.sampleHosts||[]).slice(0,8).join(', ')||'No DNS hostnames returned.')}</p></div>`:'<div class="object-placeholder"><span>⌁</span><p>Generate a plan to load the directory scope inventory.</p></div>'}</section></div></div>`;}
function planBlock(r){const p=state.plan;if(!p)return `<div class="preview-empty dryrun-empty"><span>DRY RUN / WHAT-IF</span><h3>No read-only plan generated yet.</h3><p>Select a GPO and target, then generate a plan. The preview performs no domain write.</p><div class="dryrun-features"><span>Before/after diff</span><span>Link intent</span><span>Warning aggregation</span><span>Rollback context</span></div></div>`;const before=p.preview.previousValue??'Not configured',after=p.preview.desiredValue??p.selection.customValue??p.selection.value;return `<section class="plan-card"><div class="plan-head"><div><span>DRY RUN · READ-ONLY PREVIEW</span><h2>Change plan ready</h2></div><span class="safe-badge">NO WRITE YET</span></div><div class="diff-card"><div class="diff-head"><span>BEFORE / AFTER DIFF</span><strong>${esc(r.id)}</strong></div><div class="diff-row"><div class="diff-before"><small>CURRENT</small><strong>${esc(before)}</strong></div><span class="diff-arrow">→</span><div class="diff-after"><small>DESIRED</small><strong>${esc(after)}</strong></div></div></div><div class="plan-facts"><div><span>GPO</span><strong>${esc(p.preview.gpo.name)}</strong></div><div><span>Target</span><strong>${esc(p.preview.scope.dn)}</strong></div><div><span>Link</span><strong>${p.preview.existingLink?'Existing link':'New link'}${p.selection.firstLink?' · priority 1':''}</strong></div><div><span>Execution</span><strong>${esc(p.executionUser)}</strong></div><div><span>gpupdate</span><strong>${p.preview.refreshComputers?.length?`${p.preview.refreshComputers.length} target(s)`:'Not requested'}</strong></div><div><span>Rollback</span><strong>Backup before write</strong></div></div>${p.preview.warnings?.length?`<div class="warning-list">${p.preview.warnings.map((w,i)=>`<div><b>!</b><span>${esc(w)}</span></div>`).join('')}</div>`:''}<div class="approval-box"><div class="form-section-title"><span>04</span><div><small>GOVERNANCE</small><h2>${tr('approval')}</h2></div></div><div class="form-grid"><label>Change / Ticket ID<input id="approval-ref" value="${esc(state.approval.reference)}" placeholder="CHG-2026-001"></label><label>Operator-entered approver reference (optional)<input id="approval-by" value="${esc(state.approval.approver)}" placeholder="Reference only; not identity proof"></label></div><label class="switch-row"><input id="approval-ok" type="checkbox" ${state.approval.reviewed?'checked':''}><span><b>Impact reviewed and approved</b><small>I reviewed the target, GPO, scope and potential precedence impact.</small></span></label>${state.approval.reviewed&&state.service?.writesEnabled?`<form id="gpo-apply" class="apply-box"><label class="switch-row"><input name="impact" type="checkbox" required><span><b>Confirm production impact</b><small>Backup will be created before the GPO write.</small></span></label>${p.preview.gpo.protected?`<label class="switch-row danger"><input name="protected" type="checkbox" required><span><b>Protected GPO confirmation</b><small>I explicitly approve changing this protected/default policy.</small></span></label>`:''}<label>Type APPLY to continue<input name="confirmation" required autocomplete="off" placeholder="APPLY"></label><button class="danger-action">Backup → Apply → Link → Verify</button></form>`:''}${!state.service?.writesEnabled?`<p>${say('Tətbiq üçün Sazlamalarda dəyişiklik icazəsini aktivləşdirin.','Enable changes in Settings before Apply.')}</p><button data-settings>${tr('settings')}</button>`:''}</div></section>`;}
function remediationTab(r){return `<div class="remediation-layout"><section class="content-card target-card">${targetForm(r)}</section><section>${planBlock(r)}</section></div>`;}
function verificationTimeline(h){if(!h)return `<div class="verification-empty"><div class="radar"></div><h2>No verification run for this control yet</h2><p>After Apply, this workspace will show GPO write, link, gpupdate, replication and effective-policy status.</p></div>`;const rr=h.result.refreshResults||[],v=h.result.verification,ec=h.result.endpointChecks||[];const refreshOk=rr.length&&rr.every(x=>['OK','SUCCESS','SCHEDULED'].includes(String(x.state).toUpperCase()));const effective=String(h.result.effectiveStatus||'ENDPOINT_VERIFICATION_PENDING');const effBad=/MISMATCH|FAILED/.test(effective),effOk=/VERIFIED|MATCHES/.test(effective)&&!/PENDING/.test(effective);const stages=[['GPO write',h.result.gpoPublished?'Verified':'Not confirmed',h.result.gpoPublished?'ok':'bad'],['Link verification',h.result.linkVerified?'Verified':'Not confirmed',h.result.linkVerified?'ok':'bad'],['gpupdate',rr.length?rr.map(x=>`${x.computer}: ${x.state}`).join(' · '):'Not requested',rr.length?(refreshOk?'ok':'bad'):'pending'],['AD / SYSVOL replication',v?(v.replicationConverged?'Converged across checked DCs':(v.replicationWarnings||[]).join(' · ')||'Pending'):'Not checked',v?(v.replicationConverged?'ok':'pending'):'pending'],['Effective policy',effective+(ec.length?` · ${ec.map(x=>`${x.hostname}: ${x.state}`).join(' · ')}`:''),effBad?'bad':effOk?'ok':'pending']];return `<div class="verify-timeline">${stages.map((st,i)=>`<div class="verify-node ${st[2]}"><span>${st[2]==='ok'?'✓':st[2]==='bad'?'!':i+1}</span><div><small>STAGE ${i+1}</small><h3>${st[0]}</h3><p>${esc(st[1])}</p></div></div>`).join('')}</div>`;}
function resultSummary(h){if(!h)return'';const r=h.result||{},quality=GpoUiDomain.classify(h),rr=r.refreshResults||[],before=h.plan?.preview?.previousValue??'Not configured',desired=h.plan?.preview?.desiredValue??'—',drift=quality.attention,verified=quality.compliant,endpoint=(r.endpointChecks||[])[0],actual=r.currentValue||endpoint?.actualValue||'—',rep=r.verification?.replicationConverged,scheduled=rr.filter(x=>x.state==='SCHEDULED').length,failed=rr.filter(x=>x.state==='FAILED').length;return `<section class="result-summary ${drift?'danger':verified?'success':'pending'}"><div class="result-summary-head"><div><span class="card-kicker">LIVE CHANGE RESULT</span><h2>${statusText(r.state)}</h2><p>${esc(r.message||'')}</p></div><span class="result-state ${stateClass(r.state)}">${esc(statusText(r.state))}</span></div><div class="result-diff"><div><small>BEFORE</small><strong>${esc(before)}</strong></div><span>→</span><div><small>REQUESTED</small><strong>${esc(desired)}</strong></div><span>→</span><div><small>LIVE GPO VALUE</small><strong>${esc(actual)}</strong></div></div><div class="assurance-grid"><div><small>GPO CONFIGURATION</small><strong class="${r.gpoPublished?'ok':'bad'}">${r.gpoPublished?'✓ MATCH':'! MISMATCH'}</strong></div><div><small>GPO LINK</small><strong class="${r.linkVerified?'ok':'bad'}">${r.linkVerified?'✓ ACTIVE':'! NOT VERIFIED'}</strong></div><div><small>AD / SYSVOL</small><strong class="${rep?'ok':'pending'}">${rep?'✓ CONVERGED':'· PENDING'}</strong></div><div><small>EFFECTIVE POLICY</small><strong class="${stateClass(r.effectiveStatus)}">${esc(statusText(r.effectiveStatus))}</strong></div></div>${rr.length?`<div class="refresh-summary"><span>gpupdate targets <b>${rr.length}</b></span><span>Scheduled <b>${scheduled}</b></span><span>Failed <b>${failed}</b></span></div>`:''}<div class="result-actions"><button data-verify="${esc(h.id)}" title="Reads live GPO, link, replication metadata and endpoint evidence again">↻ ${say('Canlı vəziyyəti yenidən yoxla','Re-verify live state')}</button>${h.plan?.selection?.refresh&&h.plan.selection.refresh!=='None'&&r.gpoPublished&&r.linkVerified?`<button class="primary-action compact" data-gpupdate="${esc(h.id)}" title="Schedules gpupdate /force on selected targets">${say('gpupdate /force işə sal','Run gpupdate /force')}</button>`:''}${drift?`<button class="primary-action compact danger-action" data-replan="${esc(h.id)}">${say('Yenidən remediation planı hazırla','Remediate again')}</button>`:''}<small>${say('Published, replication və endpoint-effective statusları ayrıca göstərilir. gpupdate yalnız operator seçimi ilə işləyir.','Publication, replication and endpoint-effective status are tracked separately. gpupdate only runs by explicit operator action.')}</small></div></section>`;}
function verificationTab(r){const h=relevantHistory(r)[0];return `<div class="verify-page"><div class="section-intro"><span>POST-CHANGE ASSURANCE</span><h2>Verification pipeline</h2><p>Every status below is calculated from the live GPO/link state. A previous successful run is not treated as current truth.</p></div>${resultSummary(h)}${verificationTimeline(h)}<section class="content-card evidence-card"><div class="card-title-row"><div><span class="card-kicker">EVIDENCE PACK</span><h2>Change evidence & audit bundle</h2></div><button data-evidence ${h?'':'disabled'}>Prepare JSON evidence</button></div><div class="evidence-grid"><span>Before value</span><span>Requested value</span><span>GPO & target</span><span>Operator</span><span>Backup ID</span><span>Verification</span></div><p>${h?'Evidence is generated from the latest recorded operation for this control.':'Apply and record an operation before generating evidence.'}</p></section></div>`;}
function auditTab(r){const hs=relevantHistory(r);return `<div class="audit-page"><div class="section-intro"><span>CONTROL AUDIT TRAIL</span><h2>${esc(r.id)} operation history</h2><p>Operator, target, backup and recovery context for this control.</p></div>${hs.length?`<div class="audit-table"><div class="audit-head"><span>Operation</span><span>GPO</span><span>State</span><span>Backup</span><span>Action</span></div>${hs.map(h=>`<div class="audit-row"><span><b>${esc(h.id)}</b><small>${esc(h.plan?.executionUser||'—')}</small></span><span>${esc(h.plan?.preview?.gpo?.name||'—')}</span><span><i class="state-dot ${String(h.result?.state||'').toLowerCase()}"></i>${esc(h.result?.state||'UNKNOWN')}</span><span>${esc(h.result?.backupId||'—')}</span><span><button data-verify="${esc(h.id)}">Re-verify</button></span></div>`).join('')}</div>`:`<div class="panel-empty">No operation has been recorded for this control.</div>`}</div>`;}
function controlView(){const r=state.selectedRule;if(!r)return `<div class="missing-control"><h1>${tr('noSelection')}</h1><a href="#/benchmark">${tr('back')}</a></div>`;ensureSelection();let body=state.tab==='overview'?overviewTab(r):state.tab==='remediation'?remediationTab(r):state.tab==='impact'?impactTab(r):state.tab==='verification'?verificationTab(r):auditTab(r);return `${controlHeader(r)}<div class="control-body">${body}</div>`;}
function operationsView(){
  const all=state.history,q=state.opsQuery.trim().toLowerCase();
  const matchesQuery=h=>!q||`${h.plan?.selection?.setting||''} ${h.plan?.preview?.gpo?.name||''} ${h.approval?.changeReference||''} ${h.plan?.executionUser||''} ${h.result?.state||''}`.toLowerCase().includes(q);
  const matchesFilter=h=>{const value=String(h.result?.state||'').toUpperCase();return state.opsFilter==='ALL'||(state.opsFilter==='SUCCESS'&&GpoUiDomain.classify(h).compliant)||(state.opsFilter==='FAILED'&&/FAIL|REVIEW|PARTIAL/.test(value))||(state.opsFilter==='DRIFT'&&/DRIFT|MISMATCH/.test(value))||value===state.opsFilter;};
  const drift=all.filter(h=>/DRIFT|MISMATCH/.test(String(h.result?.state||'').toUpperCase())),filtered=all.filter(h=>matchesFilter(h)&&matchesQuery(h));
  const metrics=[['ALL',say('Hamısı','All'),all.length],['SUCCESS',say('Təsdiqlənib','Verified'),all.filter(successful).length],['DRIFT','Drift',drift.length],['FAILED',say('Yoxlama tələb edir','Needs review'),all.filter(h=>/FAIL|REVIEW|PARTIAL/.test(String(h.result?.state||'').toUpperCase())).length],['ROLLED_BACK',say('Geri qaytarılıb','Rolled back'),all.filter(h=>String(h.result?.state||'').toUpperCase()==='ROLLED_BACK').length]];
  return `<header class="page-header"><div><span class="page-kicker">${say('DƏYİŞİKLİK JURNALI','CHANGE JOURNAL')}</span><h1>${tr('operations')}</h1><p>${say('Hər dəyişiklik üçün nəticə, yoxlama və bərpa məlumatlarını bir yerdə izləyin.','Track outcome, verification, and recovery details for every change.')}</p></div><a class="page-primary" href="#/benchmark">${say('Yeni plan yarat','Create new plan')} <span>→</span></a></header>
  <section class="ops-summary" aria-label="${say('Əməliyyat xülasəsi','Operation summary')}">${metrics.map(([key,label,count])=>`<button data-ops-filter="${key}" class="summary-card ${state.opsFilter===key?'active':''}"><span>${label}</span><strong>${count}</strong></button>`).join('')}</section>
  ${drift.length?`<section class="attention-panel"><div><span>${say('DİQQƏT','ATTENTION')}</span><h2>${drift.length} ${say('əməliyyatda uyğunsuzluq var','operation(s) have drift')}</h2><p>${say('Canlı vəziyyət gözlənilən nəticədən fərqlənir.','Live state differs from the expected result.')}</p></div><button data-ops-filter="DRIFT">${say('Drift-i göstər','Show drift')}</button></section>`:''}
  <section class="ops-search-panel"><div class="searchbox"><span>⌕</span><input id="ops-search" value="${esc(state.opsQuery)}" placeholder="${say('Control, GPO, dəyişiklik ID-si və ya operator axtarın','Search control, GPO, change ID, or operator')}"></div><span>${filtered.length} ${say('nəticə','result(s)')}</span></section>
  ${filtered.length?`<div class="ops-list">${filtered.map(operationCard).join('')}</div>`:`<section class="empty-state"><div class="empty-state-icon">≋</div><h2>${q?say('Axtarışa uyğun nəticə yoxdur','No matching result'):say('Hələ əməliyyat yoxdur','No operations yet')}</h2><p>${q?say('Axtarış sözünü və ya filtri dəyişin.','Adjust the search term or filter.'):say('İlk read-only planı Benchmark bölməsindən yaradın. Bütün dəyişikliklər burada görünəcək.','Create the first read-only plan from Benchmark. Every change will appear here.')}</p>${q?`<button data-ops-filter="ALL">${say('Bütününü göstər','Show all')}</button>`:`<a href="#/benchmark">${say('Benchmark-i aç','Open benchmark')} →</a>`}</section>`}`;
}
function auditView(){
  const allowed=['Administrator','Auditor'].includes(state.session?.role);
  if(!allowed)return `<section class="content-card"><h1>${say('Audit girişi məhduddur','Audit access restricted')}</h1><p>${say('Bu səhifə Auditor və Administrator rolları üçündür.','This page is available to Auditor and Administrator roles.')}</p></section>`;
  if(!state.audit)return `<section class="content-card audit-loading"><h1>${say('Audit jurnalı','Audit journal')}</h1><p>${say('Hash-chain audit hadisələri yüklənir…','Loading hash-chain audit events…')}</p><button data-load-audit>${say('Audit-i yüklə','Load audit')}</button></section>`;
  const q=state.auditQuery.trim().toLowerCase(),events=(state.audit.events||[]).filter(e=>!q||`${e.event} ${e.operator} ${e.jobId||''} ${e.controlId||''} ${e.gpoId||''} ${e.createdAt}`.toLowerCase().includes(q));
  return `<div class="hero compact"><div><span class="eyebrow">${say('DƏYİŞMƏZ HADİSƏ JURNALI','APPEND-ONLY EVENT JOURNAL')}</span><h1>${say('Audit','Audit')}</h1><p>${say('Hadisə, operator, vaxt, GPO, correlation ID və chain bütövlüyünü izləyin.','Inspect event, actor, time, GPO, correlation context, and chain integrity.')}</p></div><div class="integrity-card ${state.audit.integrityValid?'ok':'bad'}"><span>${say('CHAIN BÜTÖVLÜYÜ','CHAIN INTEGRITY')}</span><strong>${state.audit.integrityValid?say('Etibarlıdır','Valid'):say('POZULUB','BROKEN')}</strong></div></div><div class="audit-toolbar"><div class="searchbox"><span>⌕</span><input id="audit-search" value="${esc(state.auditQuery)}" placeholder="${say('Hadisə, operator, GPO və ya correlation axtar…','Search event, actor, GPO, or correlation…')}"></div><button data-export-audit>${say('JSON export','Export JSON')}</button><button data-load-audit>${say('Yenilə','Refresh')}</button></div><div class="audit-event-table" role="table"><div class="audit-event-head" role="row"><span>${say('Vaxt','Time')}</span><span>${say('Hadisə','Event')}</span><span>${say('Operator','Actor')}</span><span>GPO / Control</span><span>Hash</span></div>${events.map(e=>`<div class="audit-event-row" role="row"><span><time datetime="${esc(e.createdAt)}">${new Date(e.createdAt).toLocaleString()}</time><small>#${e.id}</small></span><span><b>${esc(e.event)}</b><small>${esc(e.jobId||'—')}</small></span><span>${esc(e.operator)}</span><span>${esc(e.gpoId||'—')}<small>${esc(e.controlId||'—')}</small></span><span class="hash-cell" title="${esc(e.hash)}">${esc(String(e.hash||'').slice(0,16))}…</span></div>`).join('')||`<div class="panel-empty">${say('Uyğun audit hadisəsi yoxdur.','No matching audit event.')}</div>`}</div>`;
}
function operationCard(h){const rr=h.result?.refreshResults||[],drift=/DRIFT|MISMATCH|REVIEW|FAIL/.test(String(h.result?.state||'')),m=h.plan?.selection?.setting||'Control';const stages=[['Preview',true],['Approved',!!h.approval],['Backup',!!h.result?.backupId||h.result?.state==='NO_CHANGE'],['Applied',!!h.result?.gpoPublished||h.result?.state==='NO_CHANGE'],['Verified',!!h.result?.linkVerified],['gpupdate',rr.length>0],['Effective',stateClass(h.result?.effectiveStatus)==='ok']];return `<article class="op-card ${drift?'needs-attention':''}"><div class="op-main"><span class="op-state ${stateClass(h.result?.state)}">${esc(statusText(h.result?.state))}</span><div><h2>${esc(m)} · ${esc(h.plan?.preview?.gpo?.name||'GPO operation')}</h2><p>${esc(h.result?.message||'')}</p><div class="op-meta"><span>${esc(h.plan?.preview?.scope?.dn||'—')}</span><span>${esc(h.plan?.executionUser||'—')}</span><span>${new Date(h.updatedAt||0).toLocaleString()}</span>${h.approval?.changeReference?`<span>Change ${esc(h.approval.changeReference)}</span>`:''}${h.correlationId?`<span title="Correlation ID">CID ${esc(h.correlationId.slice(0,12))}</span>`:''}</div></div></div><div class="op-timeline">${stages.map(([label,done])=>`<div class="${done?'done':''}"><b>${done?'✓':'·'}</b><span>${label}</span></div>`).join('')}</div><div class="op-live-diff"><div><small>BEFORE</small><strong>${esc(h.plan?.preview?.previousValue??'Not configured')}</strong></div><div><small>EXPECTED</small><strong>${esc(h.plan?.preview?.desiredValue??'—')}</strong></div><div><small>CURRENT</small><strong>${esc(h.result?.currentValue??'—')}</strong></div></div><div class="op-actions"><button data-verify="${esc(h.id)}" title="Read current live state">Re-verify</button>${h.plan?.selection?.refresh&&h.plan.selection.refresh!=='None'&&h.result?.gpoPublished&&h.result?.linkVerified?`<button data-gpupdate="${esc(h.id)}" title="Explicitly schedule gpupdate /force">gpupdate /force</button>`:''}${drift?`<button class="primary-action" data-replan="${esc(h.id)}">Remediate again</button>`:''}<button data-op-evidence="${esc(h.id)}">Evidence</button>${h.result?.state==='ROLLED_BACK'||!h.result?.backupId?'':`<form data-rollback="${esc(h.id)}"><input name="confirmation" placeholder="ROLLBACK" required aria-label="Type ROLLBACK"><button class="danger-action">Rollback</button></form>`}</div></article>`;}
function saveFavorites(){client.storage.set('gr-favorites',JSON.stringify([...state.favorites]));}
function toggleFavorite(id){state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);saveFavorites();render();}
function notifications(){const items=[];const exp=state.gpoSession?.expiresAt?new Date(state.gpoSession.expiresAt):null,mins=exp?Math.max(0,Math.ceil((exp-Date.now())/60000)):null;if(mins!=null&&mins<=5)items.push([say('Sessiya bitir','Session expiring'),say(`Delegated AD sessiyası ${mins} dəqiqəyə bitir.`,`Delegated AD session expires in ${mins} minute(s).`)]);if(state.session?.mode!=='WINDOWS')items.push(['Setup required','Windows / AD engine is not active yet.']);if(!state.inventory)items.push(['AD not connected','Connect before generating a real remediation plan.']);const review=state.history.filter(h=>/FAIL|REVIEW|PARTIAL|DRIFT|MISMATCH/.test(String(h.result?.state||'').toUpperCase())).length;if(review)items.push(['Operations need review',`${review} operation(s) require attention.`]);if(state.readiness&&!state.readiness.ready)items.push(['Environment needs attention','One or more required backend readiness checks did not pass.']);return items;}
function overlays(){const notes=notifications(),cq=state.commandQuery.trim().toLowerCase(),matches=cq?(state.catalog?.rules||[]).filter(r=>`${r.id} ${r.title}`.toLowerCase().includes(cq)).slice(0,6):[];const c=state.confirmAction;return `${state.notificationOpen?`<div class="overlay-backdrop" data-close-overlay></div><aside class="notification-panel"><div class="overlay-head"><div><span>NOTIFICATION CENTER</span><h2>Attention & status</h2></div><button data-close-overlay aria-label="Close">×</button></div><div class="notification-list">${notes.map((n,i)=>`<div><b>${i+1}</b><span><strong>${esc(n[0])}</strong><small>${esc(n[1])}</small></span></div>`).join('')||`<div class="panel-empty">${say('Diqqət tələb edən bildiriş yoxdur.','No notifications need attention.')}</div>`}</div></aside>`:''}${state.commandOpen?`<div class="command-overlay"><div class="command-palette"><div class="command-search"><span>⌘</span><input id="command-input" value="${esc(state.commandQuery)}" placeholder="Search controls or actions…" autofocus></div><div class="command-groups">${matches.length?`<small>CONTROLS</small>${matches.map(r=>`<button data-command-rule="${esc(r.id)}"><span>${esc(r.id)}</span><b>${esc(r.title)}</b><kbd>↵</kbd></button>`).join('')}`:''}<small>NAVIGATION</small><button data-command="dashboard"><span>⌂</span><b>Open Dashboard</b><kbd>G D</kbd></button><button data-command="benchmark"><span>▦</span><b>Open Benchmark</b><kbd>G B</kbd></button><button data-command="operations"><span>≋</span><b>Open Operations</b><kbd>G O</kbd></button><small>ACTIONS</small><button data-command="favorites"><span>★</span><b>Show Favorites</b><kbd>F</kbd></button><button data-command="refresh"><span>↻</span><b>Refresh environment</b><kbd>R</kbd></button></div></div></div>`:''}${c?`<div class="overlay-backdrop confirm-backdrop"></div><div class="confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><span class="confirm-icon">!</span><h2 id="confirm-title">${c.kind==='gpupdate'?say('gpupdate /force təsdiqi','Confirm gpupdate /force'):say('Rollback təsdiqi','Confirm rollback')}</h2><p>${c.kind==='gpupdate'?say('Bu əməliyyat seçilmiş endpoint-lərdə Group Policy refresh planlaşdıracaq. GPO publication və link vəziyyəti backend tərəfindən yenidən canlı yoxlanacaq.','This schedules Group Policy refresh on the selected endpoints. The backend will re-check live GPO publication and link state first.'):say('Bu əməliyyat əvvəl yaradılmış tam GPO backup-ını bərpa etməyə çalışacaq. Xarici dəyişiklik aşkarlanarsa rollback bloklanacaq.','This attempts to restore the previously created full GPO backup. Rollback is blocked if external changes are detected.')}</p><div class="confirm-actions"><button data-confirm-cancel>${say('Ləğv et','Cancel')}</button><button class="danger-action" data-confirm-run>${c.kind==='gpupdate'?say('gpupdate işə sal','Run gpupdate'):say('Rollback et','Rollback')}</button></div></div>`:''}`;}
async function downloadEvidence(){const r=state.selectedRule,h=relevantHistory(r||{})[0];if(!r||!h)return;const payload=await api('/gpo/'+h.id+'/evidence');const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`gpo-evidence-${r.id.replaceAll('.','-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function loadAudit(){state.audit=await api('/audit');}
function exportAudit(){if(!state.audit)return;const payload={exportedAt:new Date().toISOString(),integrityValid:state.audit.integrityValid,events:state.audit.events||[]},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`gpo-audit-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function applyTheme(){document.documentElement.dataset.grTheme=state.theme;client.storage.set('gr-theme',state.theme);}
function noticeTone(message){const m=String(message||'').toLowerCase();if(/fail|error|unable|blocked|invalid/.test(m))return'error';if(/warning|review|required|pending/.test(m))return'warning';if(/success|connected|generated|completed|verified|loaded/.test(m))return'success';return'info';}
function productFooter(){return `<footer class="product-footer"><span>GPO Remediator · CIS v4.0.0</span><span>${esc(state.buildLabel)}</span></footer>`;}
function busyLayer(){return state.busy?`<div class="busy-layer" role="status" aria-live="polite"><div class="busy-card"><span class="busy-spinner"></span><div><strong>Processing request</strong><small data-request-progress>Please keep this window open.</small><button type="button" data-cancel-request hidden>Stop waiting</button></div></div></div>`:'';}
let catalogRenderTimer;
function queueCatalogRender(){clearTimeout(catalogRenderTimer);catalogRenderTimer=setTimeout(render,160);}
function render(){if(!page)return;const focused=document.activeElement,focusId=page.contains(focused)?focused.id:null,caret=focused?.selectionStart;if(!state.catalog){page.innerHTML=`<section class="content-card" role="status"><h1>GPO Remediator</h1><p>${esc(state.notice||say('Benchmark kataloqu yüklənir…','Loading benchmark catalog…'))}</p><button data-refresh ${state.busy?'disabled':''}>${say('Yenidən sına','Retry')}</button><button data-settings>${tr('settings')}</button></section>${busyLayer()}`;client.localize(page);return;}applyTheme();const real=state.session?.mode==='WINDOWS';bar.innerHTML=`<div class="service-left"><span class="agent-mark"></span><div><strong>GPO Remediator</strong><small>${real?say('Windows / AD','Windows / AD'):say('Quraşdırma','Setup')} · ${real&&state.service?.writesEnabled?say('dəyişiklik icazəsi açıqdır','changes enabled'):say('yalnız baxış','read-only')}</small></div></div><div class="service-right"><button data-refresh title="${tr('refresh')}" aria-label="${tr('refresh')}">↻ <span>${tr('refresh')}</span></button><button data-theme title="${tr('theme')}" aria-label="${say('Temanı dəyiş','Toggle theme')}">${state.theme==='dark'?'☀':'◐'} <span>${state.theme==='dark'?say('Açıq','Light'):say('Tünd','Dark')}</span></button><button data-lang aria-label="${say('Dili dəyiş','Switch language')}">${state.lang.toUpperCase()}</button><button data-settings aria-label="${tr('settings')}">⚙ <span>${tr('settings')}</span></button></div>`;const route=window.GpoRouter.current();const main=((route==='#/dashboard'||route==='#/settings')?dashboardView():route==='#/benchmark'?benchmarkView():route==='#/control'?controlView():route==='#/audit'?auditView():operationsView());const toast=state.notice?`<div class="inline-notice ${noticeTone(state.notice)}" role="status" aria-live="polite"><span class="toast-mark"></span><span>${esc(state.notice)}</span></div>`:'';page.innerHTML=`<main class="product-main" aria-busy="${state.busy?'true':'false'}">${toast}${main}</main>${productFooter()}${overlays()}${busyLayer()}`;if(state.busy)page.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=true);updateNav();client.localize(page);client.localize(bar);client.localize(document.querySelector('.sidebar'));if(focusId){const input=document.getElementById(focusId);input?.focus();if(caret!=null&&input?.setSelectionRange)input.setSelectionRange(caret,caret);}}
function updateProgress(){const request=client.progress(),label=page?.querySelector('[data-request-progress]'),cancel=page?.querySelector('[data-cancel-request]');if(label&&request)label.textContent=`${state.lang==='az'?(/gpo\/(connect|discover)/.test(request.path||'')?'Domenə qoşulur':say('Sorğu icra olunur','Processing')):request.label} · ${Math.floor((Date.now()-request.started)/1000)} / ${Math.round(request.timeout/1000)} ${say('saniyə','seconds')}`;if(cancel){cancel.hidden=!request?.cancelable;cancel.disabled=!request?.cancelable;}}
async function run(fn){if(state.busy)return;state.busy=true;state.notice='';let timer;try{render();timer=setInterval(updateProgress,250);await fn();}catch(e){state.notice=(e.message||'Error')+' — '+errorGuidance(e);}finally{clearInterval(timer);state.busy=false;render();}}
async function refresh(){
  await loadCatalog();state.session=await api('/session');state.service=await api('/service');installNav(document.querySelector('.sidebar nav'));
  if(state.session.mode!=='WINDOWS'){state.settings=[];state.history=[];state.inventory=null;state.gpoSession=null;state.readiness=null;state.readinessError='';state.plan=null;syncBackendMappings();return;}
  [state.settings,state.history]=await Promise.all([api('/gpo/settings'),api('/gpo/history')]);syncBackendMappings();
  try{[state.inventory,state.gpoSession]=await Promise.all([api('/gpo/inventory'),api('/gpo/session')]);}catch(e){state.gpoSession=null;if(e.code!=='GPO_LOGIN_REQUIRED')throw e;}
}
async function checkReadiness(){state.readinessError='';try{state.readiness=await api('/gpo/readiness');if(!state.readiness.ready)state.notice=say('Bağlantı yoxlamasında problem var. Aşağıdakı nəticələri nəzərdən keçirin.','Connection checks need attention. Review the results below.');}catch(e){state.readiness=null;state.readinessError=e.message;state.notice=e.message;}}
function captureForm(){const f=page.querySelector('#gpo-selection');if(!f)return;const st=state.settings.find(x=>x.id===state.selectedRule?.backendSetting);state.selection.scopeDn=f.elements.scopeDn?.value??state.selection.scopeDn;state.selection.refresh=f.elements.refresh?.value??state.selection.refresh;state.selection.accountScope=st?.domainPolicySensitive?'Domain':'LocalComputers';if(f.elements.value)state.selection.value=Number(f.elements.value.value);if(f.elements.customValue)state.selection.customValue=f.elements.customValue.value;state.selection.firstLink=!!f.elements.firstLink?.checked;state.selection.setting=state.selectedRule?.backendSetting||'';}
function selectRule(id){state.selectedRule=state.catalog.rules.find(r=>r.id===id);state.plan=null;state.tab='overview';state.selection.gpoId='';state.selection.scopeDn='';state.selection.customValue='';state.selection.value=state.settings.find(x=>x.id===state.selectedRule?.backendSetting)?.suggested??0;state.selection.refresh='None';state.selection.firstLink=false;state.approval={reference:'',approver:'',reviewed:false};state.gpoSearch='';state.gpoPickerOpen=false;ensureSelection();location.hash='#/control';}
function updateNav(){document.querySelectorAll('[data-gpo-nav]').forEach(a=>a.classList.toggle('selected',a.hash===location.hash||(location.hash==='#/control'&&a.hash==='#/benchmark')));}
function installNav(nav){nav.replaceChildren();const items=[['#/dashboard','⌂',tr('dashboard')],['#/benchmark','▦',tr('benchmark')],['#/operations','≋',tr('operations')]];if(['Administrator','Auditor'].includes(state.session?.role))items.push(['#/audit','⌁',say('Audit','Audit')]);for(const [href,icon,label] of items){const a=document.createElement('a');a.href=href;a.className='nav-link';a.dataset.gpoNav='';a.innerHTML=`<span class="nav-icon">${icon}</span><span>${label}</span>`;nav.append(a);}const set=document.createElement('button');set.className='nav-link';set.dataset.settingsNav='';set.innerHTML=`<span class="nav-icon">⚙</span><span>${tr('settings')}</span>`;set.onclick=()=>window.dispatchEvent(new CustomEvent('gr:open'));nav.append(set);}
function mount(){const workspace=document.querySelector('.workspace'),nav=document.querySelector('.sidebar nav');if(!workspace||!nav)return;document.body.classList.add('operator-custom-page');installNav(nav);if(!document.getElementById('service-bar')){bar=document.createElement('div');bar.id='service-bar';workspace.prepend(bar);page=document.createElement('section');page.id='operator-modules';workspace.insertBefore(page,bar.nextSibling);
page.addEventListener('click',e=>{if(e.target.closest('[data-cancel-request]')){client.cancelReadOnly();return;}if(state.busy)return;if(e.target.closest('[data-load-audit]')){run(loadAudit);return;}if(e.target.closest('[data-export-audit]')){exportAudit();return;}if(e.target.closest('[data-refresh]')){run(refresh);return;}const dom=e.target.closest('[data-domain]');if(dom){const id=dom.dataset.domain,was=state.expandedTop.has(id);state.expandedTop.clear();if(!was)state.expandedTop.add(id);render();return;}const sub=e.target.closest('[data-subsection]');if(sub){const id=sub.dataset.subsection;state.expandedSub.has(id)?state.expandedSub.delete(id):state.expandedSub.add(id);render();return;}const rule=e.target.closest('[data-rule]');if(rule){selectRule(rule.dataset.rule);return;}const fav=e.target.closest('[data-favorite]');if(fav){e.preventDefault();e.stopPropagation();toggleFavorite(fav.dataset.favorite);return;}const view=e.target.closest('[data-view]');if(view){state.savedView=view.dataset.view;render();return;}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render();return;}if(e.target.closest('[data-back]')){location.hash='#/benchmark';return;}if(e.target.closest('[data-gpo-toggle]')){state.gpoPickerOpen=!state.gpoPickerOpen;render();return;}const gp=e.target.closest('[data-gpo]');if(gp){state.selection.gpoId=gp.dataset.gpo;state.gpoPickerOpen=false;state.gpoSearch='';state.plan=null;render();return;}if(e.target.closest('[data-readiness]')){run(checkReadiness);return;}if(e.target.closest('[data-discover]'))run(async()=>{state.inventory=await api('/gpo/discover',{});state.notice='GPO inventory refreshed.';await checkReadiness();});if(e.target.closest('[data-disconnect]'))run(async()=>{await api('/gpo/disconnect',{});state.inventory=null;state.gpoSession=null;state.readiness=null;state.readinessError='';state.plan=null;});if(e.target.closest('[data-settings]'))window.dispatchEvent(new CustomEvent('gr:open'));const of=e.target.closest('[data-ops-filter]');if(of){state.opsFilter=of.dataset.opsFilter;render();return;}const v=e.target.closest('[data-verify]');if(v)run(async()=>{const rr=await api('/gpo/'+v.dataset.verify+'/verify',{});state.history=await api('/gpo/history');state.notice=rr.result.message;});const gu=e.target.closest('[data-gpupdate]');if(gu){state.confirmAction={kind:'gpupdate',id:gu.dataset.gpupdate};render();return;}const rp=e.target.closest('[data-replan]');if(rp)run(async()=>{const p=await api('/gpo/'+rp.dataset.replan+'/replan',{});state.plan=p;const rule=state.catalog.rules.find(x=>(x.backendSetting||x.id)===p.selection.setting);if(rule)state.selectedRule=rule;state.selection={...state.selection,...p.selection};state.approval={reference:'',approver:'',reviewed:false};state.tab='remediation';state.notice=say('Canlı vəziyyətdən yeni remediation planı yaradıldı. Apply-dan əvvəl planı yenidən yoxlayın.','A fresh remediation plan was created from the live state. Review it before Apply.');location.hash='#/control';});const oe=e.target.closest('[data-op-evidence]');if(oe)run(async()=>{const payload=await api('/gpo/'+oe.dataset.opEvidence+'/evidence');const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`gpo-evidence-${oe.dataset.opEvidence}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});const op=e.target.closest('[data-op]');if(op){location.hash='#/operations';return;}if(e.target.closest('[data-evidence]')){run(async()=>{await downloadEvidence();state.notice=say('Hesabat endirildi.','Report downloaded.');});return;}if(e.target.closest('[data-close-overlay]')||e.target.classList.contains('command-overlay')){state.commandOpen=false;state.commandQuery='';state.notificationOpen=false;render();return;}if(e.target.closest('[data-confirm-cancel]')){state.confirmAction=null;render();return;}if(e.target.closest('[data-confirm-run]')&&state.confirmAction){const a={...state.confirmAction};state.confirmAction=null;if(a.kind==='gpupdate')run(async()=>{const rr=await api('/gpo/'+a.id+'/refresh',{});state.history=await api('/gpo/history');state.notice=rr.result.state+': '+rr.result.message;state.tab='verification';});if(a.kind==='rollback')run(async()=>{const result=await api('/gpo/'+a.id+'/rollback',{confirmation:a.confirmation});state.history=await api('/gpo/history');state.notice=result.result.state+': '+result.result.message;});return;}const cr=e.target.closest('[data-command-rule]');if(cr){state.commandOpen=false;state.commandQuery='';selectRule(cr.dataset.commandRule);return;}const cmd=e.target.closest('[data-command]');if(cmd){const c=cmd.dataset.command;if(c==='dashboard')location.hash='#/dashboard';if(c==='benchmark')location.hash='#/benchmark';if(c==='operations')location.hash='#/operations';if(c==='favorites'){state.savedView='FAVORITES';location.hash='#/benchmark';}if(c==='refresh')run(refresh);state.commandOpen=false;render();return;}});
page.addEventListener('input',e=>{if(e.target.id==='audit-search'){state.auditQuery=e.target.value;render();return;}if(e.target.id==='catalog-search'){state.query=e.target.value;queueCatalogRender();return;}if(e.target.id==='gpo-search'){state.gpoSearch=e.target.value;render();return;}if(e.target.id==='ops-search'){state.opsQuery=e.target.value;render();return;}if(e.target.id==='command-input'){state.commandQuery=e.target.value;render();return;}if(e.target.id==='approval-ref')state.approval.reference=e.target.value;if(e.target.id==='approval-by')state.approval.approver=e.target.value;if(e.target.id==='approval-ok'){state.approval.reviewed=e.target.checked;render();}if(e.target.closest('#gpo-selection')){captureForm();state.plan=null;}});
page.addEventListener('change',e=>{if(e.target.id==='catalog-level'){state.level=e.target.value;render();}if(e.target.id==='catalog-automation'){state.automation=e.target.value;render();}if(e.target.closest('#gpo-selection')){captureForm();state.plan=null;render();}});
page.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='gpo-login'){const login={userName:f.elements.userName.value.trim().replaceAll('/','\\'),password:f.elements.password.value};run(async()=>{try{state.inventory=await api('/gpo/connect',login);state.gpoSession=await api('/gpo/session');login.password='';state.notice=say('Domenə qoşuldu. GPO siyahısı yükləndi.','Connected. GPO list loaded.');await checkReadiness();}finally{login.password='';}});}if(f.id==='gpo-selection'){captureForm();if(!state.selectedRule?.backendSetting)return;run(async()=>{state.plan=await api('/gpo/preview',state.selection);state.notice=say('Plan hazırdır. Heç bir siyasət dəyişdirilməyib.','Plan ready. No policy has been changed.');});}if(f.id==='gpo-apply'&&state.plan){const id=state.plan.id,payload={confirmation:f.elements.confirmation.value,acknowledgeImpact:f.elements.impact.checked,acknowledgeProtected:!!f.elements.protected?.checked,changeReference:state.approval.reference.trim(),approvedBy:state.approval.approver.trim()};run(async()=>{const result=await api('/gpo/'+id+'/apply',payload);state.plan=null;state.history=await api('/gpo/history');state.notice=result.result.state+': '+result.result.message;state.tab='verification';});}if(f.dataset.rollback){const id=f.dataset.rollback,confirmation=f.elements.confirmation.value;if(confirmation!=='ROLLBACK'){state.notice=say('Davam etmək üçün ROLLBACK yazın.','Type ROLLBACK to continue.');render();return;}state.confirmAction={kind:'rollback',id,confirmation};render();}});
bar.addEventListener('click',e=>{if(e.target.closest('[data-command-open]')){state.commandOpen=true;state.notificationOpen=false;render();return;}if(e.target.closest('[data-notifications]')){state.notificationOpen=true;state.commandOpen=false;render();return;}if(e.target.closest('[data-settings]'))window.dispatchEvent(new CustomEvent('gr:open'));if(e.target.closest('[data-refresh]'))run(refresh);if(e.target.closest('[data-theme]')){state.theme=state.theme==='dark'?'light':'dark';client.storage.set('gr-theme',state.theme);render();}if(e.target.closest('[data-lang]')){state.lang=state.lang==='az'?'en':'az';window.GpoI18n.setLanguage(state.lang);client.storage.set('gr-lang',state.lang);nav.querySelectorAll('[data-gpo-nav],[data-settings-nav]').forEach(x=>x.remove());installNav(nav);render();}});}
updateNav();}
async function init(){mount();window.GpoRouter.ensure();window.addEventListener('gr:refresh',()=>run(refresh));window.addEventListener('gr:connection-expired',()=>{state.inventory=null;state.readiness=null;state.plan=null;state.notice=say('Domen bağlantısı yenilənməlidir. Yenidən qoşulun.','Reconnect to the domain.');render();});window.addEventListener('hashchange',()=>{if(window.GpoRouter.ensure()!==location.hash)return;mount();render();if(location.hash==='#/audit'&&!state.audit&&['Administrator','Auditor'].includes(state.session?.role))run(loadAudit);});window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.commandOpen=!state.commandOpen;state.notificationOpen=false;render();return;}if(e.key==='Escape'&&(state.commandOpen||state.notificationOpen||state.gpoPickerOpen||state.confirmAction)){state.commandOpen=false;state.commandQuery='';state.notificationOpen=false;state.gpoPickerOpen=false;state.confirmAction=null;render();return;}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();window.GpoRouter.navigate('#/benchmark');setTimeout(()=>document.getElementById('catalog-search')?.focus(),60);}});await run(refresh);if(location.hash==='#/audit'&&['Administrator','Auditor'].includes(state.session?.role))await run(loadAudit);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
